                opened ? c.number() : null, status == ClaimStatus.SETTLED ? c.due() : null, opened ? c.openedBy() : null,
                stated, stated ? c.statedDue() : null, c.corrects(), c.dueBy(), c.deferredUntil(), c.proofs(),
