package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: who opens or closes the claim's editor (a blank name is refused). */
public class ValidateLock {
    public void validate(@RequestBody LockRequest request, Out<ClaimLock> lock) throws InvalidClaimStatusException {
        String by = request == null || request.by() == null ? "" : request.by().trim();
        if (by.isEmpty()) {
            throw new InvalidClaimStatusException("Who opens the editor is required");
        }
        lock.set(new ClaimLock(by));
    }
}
package net.officefloor.hq.app.claim;

/** Body of opening or closing a claim's editor: who does it. */
public record LockRequest(String by) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidClaimStatus {
    public void handle(@Parameter InvalidClaimStatusException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
    }
}
-- Who holds a claim's editor open (the user who pressed its edit button), so no one else can open it until it is
-- saved or cancelled or the sheet's today changes. Null when no one does.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(200);
-- The people each user watches, per sheet: a user watches a person at most once. The id keeps the order they started
-- watching, so a watched person's settled claim notifies the watchers in that order.
CREATE TABLE watch (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200) NOT NULL,
    person_id  BIGINT       NOT NULL REFERENCES person (id),
    user_name  VARCHAR(200) NOT NULL,
    CONSTRAINT watch_unique UNIQUE (sheet_id, person_id, user_name)
);
