package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Stores the edit and releases the claim's lock; refused when the claim is no longer a DRAFT or another user holds
 *  its lock (has its editor open). */
public class SaveClaim {
    public void save(@Val Claim claim, @Val ClaimValues values, ClaimRepository claims) throws InvalidClaimException {
        if (!claims.update(claim, values.by())) {
            throw new InvalidClaimException("Only a DRAFT claim no one else is editing can be edited");
        }
    }
}
# PUT /api/sheets/{sheetId}/claims/{claimId} — edit a claim's amount, date and note, validated as an
# add (a blank date takes the sheet's today). Only a DRAFT claim can be edited: any other is a 400. A claim dated, or moved, inside a closed period is a 400. Invalid values are a 400 and a claim not on the sheet a
# 404, neither writing anything. A claim another user is editing (holds its lock) is a 400. Saving releases the
# claim's lock. Responds with the claim as stored.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimEdited
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
package net.officefloor.hq.app.claim;

import java.sql.Date;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The stored status logs of the claims, kept per sheet, each claim's lines oldest first. */
@Repository
public class ClaimLogRepository {

    private final JdbcTemplate jdbc;

    public ClaimLogRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void add(String sheetId, ClaimLogLine line) {
        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, log_date, due) VALUES (?, ?, ?, ?, ?, ?)",
                sheetId, line.claimId(), line.status().name(), line.by(), Date.valueOf(line.date()), line.due());
    }

    /** The claim's lines, oldest first. */
    public List<ClaimLogLine> of(String sheetId, long claimId) {
        return jdbc.query("SELECT claim_id, status, by_user, log_date, due FROM claim_log WHERE sheet_id = ? AND claim_id = ? ORDER BY id",
                ClaimLogRepository::map, sheetId, claimId);
    }

    /** Every claim's lines on the sheet, by claim id, each oldest first. */
    public Map<Long, List<ClaimLogLine>> bySheet(String sheetId) {
        return jdbc.query("SELECT claim_id, status, by_user, log_date, due FROM claim_log WHERE sheet_id = ? ORDER BY id",
                ClaimLogRepository::map, sheetId).stream()
                .collect(Collectors.groupingBy(ClaimLogLine::claimId, LinkedHashMap::new, Collectors.toList()));
    }

    private static ClaimLogLine map(ResultSet rs, int n) throws SQLException {
        return new ClaimLogLine(rs.getLong("claim_id"), ClaimStatus.valueOf(rs.getString("status")),
                rs.getString("by_user"), rs.getObject("log_date", LocalDate.class), rs.getString("due"));
    }
}

